import{_ as e,o as r,c as d,a2 as a}from"./chunks/framework.CFuv5BrO.js";const b=JSON.parse('{"title":"Hearth OS · 工作区隔离与产物设计说明","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/Hearth-工作区隔离与产物设计说明.md","filePath":"architecture/Hearth-工作区隔离与产物设计说明.md","lastUpdated":null}'),o={name:"architecture/Hearth-工作区隔离与产物设计说明.md"};function h(i,t,s,c,l,n){return r(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="hearth-os-·-工作区隔离与产物设计说明" tabindex="-1">Hearth OS · 工作区隔离与产物设计说明 <a class="header-anchor" href="#hearth-os-·-工作区隔离与产物设计说明" aria-label="Permalink to &quot;Hearth OS · 工作区隔离与产物设计说明&quot;">​</a></h1><blockquote><p>本文只依据项目源码整理（<code>apps/server/src</code> 下工作区、worktree、Git 视图、任务级依赖环境、项目与沙箱相关文件，以及 <code>packages/templates</code>），未参考 <code>docs/</code> 与 <code>README.md</code>；文中不列举任何具体代码，括号内的文件名仅用于定位核对。 整理日期：2026-11-13</p></blockquote><p><strong>本文边界（避免与本套其它说明重复）</strong></p><table tabindex="0"><thead><tr><th>已讲过的内容</th><th>在哪份文档</th><th>本文的处理</th></tr></thead><tbody><tr><td>产物如何发布、长文本如何内容寻址、路径安全</td><td><a href="./Hearth-存储设计说明.html">Hearth-存储设计说明</a></td><td>不重复，只讲隔离与 Git 层</td></tr><tr><td>十六个内置工具与权限模型</td><td><a href="./Hearth-Agent运行时设计说明.html">Hearth-Agent运行时设计说明</a></td><td>不展开</td></tr><tr><td>网页抓取净化规则、GitHub 副作用执行</td><td><a href="./Hearth-数据源与联网设计说明.html">Hearth-数据源与联网设计说明</a></td><td>这里只讲工作区与 Git 视图，副作用交给那篇</td></tr><tr><td>模板与意图关键词如何影响选路</td><td><a href="./意图识别路由与执行器自动选择.html">意图识别路由与执行器自动选择</a></td><td>不展开</td></tr></tbody></table><p>本文只讲：<strong>模型开跑之前，磁盘上要准备什么；改代码时怎么隔离；改完怎么给人看</strong>。</p><hr><h2 id="_0-一句话总览" tabindex="-1">0. 一句话总览 <a class="header-anchor" href="#_0-一句话总览" aria-label="Permalink to &quot;0. 一句话总览&quot;">​</a></h2><p>这是「物理准备层」：把各种输入落成文件、在真实 Git 仓库上开出隔离工作树、按模板声明装好 Python/Node 依赖，再提供只读的 diff、文件与 PR 预览视图。它不负责跑模型，也不负责判定任务是否成功。</p><hr><h2 id="_1-先定性-三个容易误解的地方" tabindex="-1">1. 先定性：三个容易误解的地方 <a class="header-anchor" href="#_1-先定性-三个容易误解的地方" aria-label="Permalink to &quot;1. 先定性：三个容易误解的地方&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>代码里的实际做法</th></tr></thead><tbody><tr><td>以为服务端 <code>runtime.ts</code> 是 Agent 运行时</td><td>它是<strong>装依赖的脚本编排器</strong>（虚拟环境、包安装），与共享包 <code>agent-runtime</code> 毫无关系</td></tr><tr><td>以为「沙箱」是个容器</td><td>它只是路径、网络、工具、进程的<strong>策略求值器</strong>；五种后端枚举里实际只用了本地后端</td></tr><tr><td>以为模板里的验收描述会变成结构化验收项</td><td>取模板时验收字段被统一映射成<strong>空数组</strong>，真正的验收项来自别处</td></tr></tbody></table><hr><h2 id="_2-工作区-输入落地与提示词" tabindex="-1">2. 工作区：输入落地与提示词 <a class="header-anchor" href="#_2-工作区-输入落地与提示词" aria-label="Permalink to &quot;2. 工作区：输入落地与提示词&quot;">​</a></h2><p>每个任务有自己的目录，下面分「输入」与「输出」两块。不同类型输入落成不同文件：纯文本与粘贴内容落成 Markdown 或纯文本，网页落成页面 Markdown 加元数据，GitHub 上下文落成说明与结构化数据，附件落成副本。随后生成任务提示词，路径解析被约束在工作区内。</p><p>有一个很用心的防幻觉设计：如果 URL 输入抓取失败，系统会写一份<strong>说明失败原因的 Markdown</strong>，并明确禁止模型据此补写正文。这样模型不会把「抓不到」当成「内容为空」而凭空编造。致命错误（非法地址、协议不支持、地址带凭据、主机不允许、私网地址等）与非致命错误是分开处理的。</p><p>产物侧的总量闸门是 1000 个文件、合计 100 MB；只有落在受管输出目录下的文件才被认作产物（发布流程见存储文档）。</p><hr><h2 id="_3-git-工作树-一任务一分支" tabindex="-1">3. Git 工作树：一任务一分支 <a class="header-anchor" href="#_3-git-工作树-一任务一分支" aria-label="Permalink to &quot;3. Git 工作树：一任务一分支&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>规则</th></tr></thead><tbody><tr><td>分支名</td><td>固定前缀加任务编号</td></tr><tr><td>路径</td><td>工作区根目录下的独立 worktrees 子目录</td></tr><tr><td>创建</td><td>先校验分支名合法性，再执行添加；分支已存在则复用，否则从基准提交新建</td></tr><tr><td>视图校验</td><td>当前分支不符时直接标记「不可用」</td></tr><tr><td>清理</td><td>要求工作树干净，否则拒绝；删除分支失败仍会返回「已移除但分支保留」</td></tr></tbody></table><p>错误分类很细：缺少项目、项目路径失效、不是 Git 仓库、分支名非法、分支不匹配、工作树脏。Git 命令统一 30 秒超时。</p><p>「清理成功」不等于「分支已删除」——返回值里单独有一个标记说明分支是否还在，这是排查残留分支时最该看的一项。</p><hr><h2 id="_4-只读-git-视图与-pr-预览" tabindex="-1">4. 只读 Git 视图与 PR 预览 <a class="header-anchor" href="#_4-只读-git-视图与-pr-预览" aria-label="Permalink to &quot;4. 只读 Git 视图与 PR 预览&quot;">​</a></h2><p>视图服务把若干 Git 命令的结果聚合成一份给界面用的快照：当前提交、当前分支、工作区状态、与基准的差异统计、提交数、最近若干条提交。上限是差异 512 KB、单文件 1 MB、提交列表 20 条；路径读取有防越界校验。</p><p><strong>一个隐藏回退</strong>：如果没有独立工作树，视图会去任务目录下的 <code>repo</code> 子目录找仓库（那是 GitHub 浅克隆落点）。两条来源共用同一套差异视图，所以无论任务改的是本地项目还是远程 PR，界面看到的结构一致。</p><p>PR 预览是一份产出文件，校验规则包括：标题与正文必填、标题不超过 160 字、正文不超过 6 万字符、有关联议题时正文必须包含引用、分支与基准必须与仓库上下文严格一致。评论正文从评审稿里用成对标记抠出，标记有两套兼容写法。</p><hr><h2 id="_5-任务级依赖环境" tabindex="-1">5. 任务级依赖环境 <a class="header-anchor" href="#_5-任务级依赖环境" aria-label="Permalink to &quot;5. 任务级依赖环境&quot;">​</a></h2><p>按任务模板里的声明预装依赖，产物写在任务目录的隐藏子目录里：一个说明文件记录可用的 Python / Node 可执行路径，一份准备日志。</p><table tabindex="0"><thead><tr><th>项</th><th>规则</th></tr></thead><tbody><tr><td>Python</td><td>优先用 uv 建虚拟环境并装依赖，失败回退到标准 venv 与 pip</td></tr><tr><td>Node</td><td>按声明走 <code>ci</code> 或 <code>install</code></td></tr><tr><td>安装超时</td><td>20 分钟</td></tr><tr><td>日志上限</td><td>20 万字符，超限保留末尾并加截断说明</td></tr></tbody></table><p>这是一层「让模型拿到能跑的环境」的保障，与模型调用、工具循环完全无关。</p><hr><h2 id="_6-模板与本地项目" tabindex="-1">6. 模板与本地项目 <a class="header-anchor" href="#_6-模板与本地项目" aria-label="Permalink to &quot;6. 模板与本地项目&quot;">​</a></h2><p>任务模板是纯声明式数据：编号、标题、类别、描述、目标、输入定义、允许的网络主机、输出目录、期望产物、验收说明、审批类型、GitHub 上下文、运行时声明。类别有文档、网页、代码、数据、人物、营销六类，实际定义 15 个模板。</p><p>本地项目注册要求路径是 Git 仓库根且默认分支本地存在；路径支持展开用户目录并解析真实路径；名称清洗后上限 100 字符。项目是开工作树的前提。</p><blockquote><p>前面提到的「验收字段被映射为空数组」值得再强调一次：模板里的验收描述只是给人看的说明，不会自动变成完成判定里的结构化验收项。</p></blockquote><hr><h2 id="_7-沙箱-策略求值而非隔离容器" tabindex="-1">7. 沙箱：策略求值而非隔离容器 <a class="header-anchor" href="#_7-沙箱-策略求值而非隔离容器" aria-label="Permalink to &quot;7. 沙箱：策略求值而非隔离容器&quot;">​</a></h2><p>沙箱服务定义五种后端（本地、容器、SSH、虚拟机、远程 worker）与五类失败（逃逸、网络违规、凭据过期、策略拒绝、后端不可用），但当前只注册了本地后端，其余是枚举占位。</p><p>它的一次求值会根据输入判断是否需要审批，而判据<strong>只看「是否属于外部副作用」这一个布尔值</strong>，不看路径或网络是否越界。真正的路径与网络拦截发生在 Agent 运行时的工具层（见<a href="./Hearth-Agent运行时设计说明.html">Hearth-Agent运行时设计说明</a>）。</p><hr><h2 id="_8-只读代码才会发现的事实" tabindex="-1">8. 只读代码才会发现的事实 <a class="header-anchor" href="#_8-只读代码才会发现的事实" aria-label="Permalink to &quot;8. 只读代码才会发现的事实&quot;">​</a></h2><ol><li>服务端 <code>runtime.ts</code> 是装依赖的，不是 Agent 运行时。</li><li>模板的验收说明不会变成结构化验收项。</li><li>工作树清理成功时分支可能仍在。</li><li>五种沙箱后端只有本地后端落地；是否需要审批只看外部副作用标记。</li><li>无工作树时 Git 视图会回退到任务目录下的浅克隆仓库。</li><li>URL 抓取失败会写一份「失败说明」并禁止模型补写，这是明确的防幻觉措施。</li></ol><hr><h2 id="_9-与其它模块的分界" tabindex="-1">9. 与其它模块的分界 <a class="header-anchor" href="#_9-与其它模块的分界" aria-label="Permalink to &quot;9. 与其它模块的分界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>内容</th></tr></thead><tbody><tr><td>输入</td><td>任务记录、项目记录、任务模板、来源条目与附件、权限定义</td></tr><tr><td>输出</td><td>工作区与输入文件、任务提示词、工作树路径与分支、Git 差异视图、依赖环境路径、PR 预览数据</td></tr><tr><td>不讲</td><td>产物发布与内容寻址（存储）、工具权限（Agent 运行时）、GitHub 副作用（数据源）、完成判定（执行调度器）</td></tr></tbody></table><hr><h2 id="附-源码定位索引" tabindex="-1">附：源码定位索引 <a class="header-anchor" href="#附-源码定位索引" aria-label="Permalink to &quot;附：源码定位索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>想看什么</th><th>去哪找</th></tr></thead><tbody><tr><td>工作区结构与输入落地、提示词生成</td><td><code>apps/server/src/workspace.ts</code></td></tr><tr><td>工作树创建 / 校验 / 清理</td><td><code>apps/server/src/worktrees.ts</code></td></tr><tr><td>差异、文件与提交视图</td><td><code>apps/server/src/task-git.ts</code></td></tr><tr><td>任务级依赖环境准备</td><td><code>apps/server/src/runtime.ts</code></td></tr><tr><td>本地项目注册</td><td><code>apps/server/src/projects.ts</code></td></tr><tr><td>沙箱策略求值</td><td><code>apps/server/src/sandbox.ts</code></td></tr><tr><td>模板定义</td><td><code>packages/templates/src/index.ts</code></td></tr><tr><td>产物闸门（发布流程见存储文档）</td><td><code>apps/server/src/artifacts.ts</code></td></tr><tr><td>GitHub 仓库准备与 PR 预览校验</td><td><code>apps/server/src/github.ts</code></td></tr></tbody></table>',49)])])}const _=e(o,[["render",h]]);export{b as __pageData,_ as default};
